""" Return the bounding vertices of the texture square.
    """
def tex_coord(x: Any, y: Any, n: Any = 8) -> object {
    m = 1.0 / n;
    dx = x * m;
    dy = y * m;
    return (dx, dy, (dx + m), dy, (dx + m), (dy + m), dx, (dy + m));
}

""" Perform regular simple expression matching

    Given an input string s and a pattern p, run regular expression
    matching with support for '.' and '*'.

    Parameters
    ----------
    s : str
        The string to match.
    p : str
        The pattern to match.

    Returns
    -------
    bool
        Was it a match or not.
    """
def isMatch(s: Any, p: Any) -> object {
    dp = [([False] * (len(p) + 1)) for _ in range((len(s) + 1))];
    dp[0][0] = True;
    for ii in range(1, len(p)) {
        if ((p[ii] == "*") and dp[0][(ii - 1)]) {
            dp[0][(ii + 1)] = True;
        }
    }
    for ii in range(len(s)) {
        for jj in range(len(p)) {
            if (p[jj] in {s[ii], '.'}) {
                dp[(ii + 1)][(jj + 1)] = dp[ii][jj];
            } elif (p[jj] == '*') {
                if (p[(jj - 1)] not in {s[ii], '.'}) {
                    dp[(ii + 1)][(jj + 1)] = dp[(ii + 1)][(jj - 1)];
                } else {
                    dp[(ii + 1)][(jj + 1)] = (
                        dp[ii][(jj + 1)] or dp[(ii + 1)][jj] or dp[(ii + 1)][(jj - 1)]
                    );
                }
            }
        }
    }
    return dp[-1][-1];
}

